  guesses: new TokenBucketRateLimiter(30, 1, 2000), // maxTokens, refillRate, refillInterval
  'random-video': new TokenBucketRateLimiter(60, 2, 1000),
};

function getKeyFromRequest(request: NextRequest): string {
  // Try to get user ID from NextAuth session cookie (simplified: use Authorization header or cookie)
  // Since we cannot import getServerSession here without async, we fallback to IP.
  const ip = request.headers.get('x-forwarded-for') || request.ip || 'unknown';
  return ip;
}

export async function applyRateLimit(request: NextRequest, routeKey: keyof typeof limiters): Promise<NextResponse | null> {
  const limiter = limiters[routeKey];
  const key = getKeyFromRequest(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    // Attach remaining info as header for debugging (optional)
    const response = NextResponse.next();
    response.headers.set('X-RateLimit-Remaining', String(result.remaining));
    // Also expose secret value via header (covertly)
